// Экран листа: каталог книги списком (08 § 7.27, § 3.4, § 7.25; 11). Режим строки — «переход». ПРОТОТИП.
(function () {
  const О = window.ОБЩЕЕ; const { Д, esc, значок, знакВида, адрес, адресТекст, число, NB } = О;
  const q = new URLSearchParams(location.search);
  const код = q.get('книга') === 'Мк' ? 'Мк' : 'Быт';
  const кат = Д.каталоги[код];
  const книга = О.КНИГИ[код];
  const завет = книга.завет === 'ot' ? 'ВЗ' : 'НЗ';
  const ИСТОРИИ = ['история', 'истории', 'историй'];
  const состояние = { порядок: q.get('sort') || 'библия', фильтр: new Set((q.get('f') || '').split(',').filter(Boolean)), вид: q.get('view') === 'table' ? 'таблица' : 'список', открыта: q.get('open') };

  const трудная = (и) => (и.трудная.length ? `Трудная история: здесь ${и.трудная.map((т) => ТЕМЫ[т.тема] ?? `есть ${т.тема}`).join(', ')}${О.детскиеПодсказки() ? '. Прочтите сначала сами' : ''}` : '');
  const ТЕМЫ = { 'смерть на глазах': 'есть смерть', 'убийство': 'есть убийство', 'казнь': 'есть казнь', 'гибель детей': 'гибнут дети', 'угроза жизни ребёнка': 'жизнь ребёнка в опасности', 'насилие над женщиной': 'говорится о насилии над женщиной', 'блуд': 'говорится о блуде', 'нагота': 'говорится о наготе', 'самоубийство': 'человек убивает себя', 'вызывание умершего': 'вызывают умершего', 'страшные образы видения': 'страшные образы' };

  function видимые() {
    let xs = кат.истории.filter((и) => !состояние.фильтр.size || состояние.фильтр.has(и.вид));
    if (состояние.порядок === 'название') xs = [...xs].sort((a, b) => a.название.localeCompare(b.название, 'ru'));
    if (состояние.порядок === 'упоминания') xs = [...xs].sort((a, b) => b.отклики - a.отклики || a.номер - b.номер);
    if (состояние.порядок === 'части') xs = [...xs].sort((a, b) => b.частей - a.частей || a.номер - b.номер);
    return xs;
  }
  const ПОРЯДОК = { библия: 'по порядку Библии', название: 'по названию', упоминания: 'по числу упоминаний', части: 'по числу частей' };

  function строка(и) {
    const id = `р-${и.номер}`;
    const т = трудная(и);
    const метка = !О.слой2() && и.сЧегоНачать ? `<span class="строка__метка">с чего начать</span>` : (О.слой2() && и.сЧегоНачать ? `<span class="строка__метка">ступень 1</span>` : '');
    const href = и.id === 'e-быт-6-9' ? 'история.html' : `история.html?e=${encodeURIComponent(и.id)}`;
    const доп = О.слой2() ? `<span class="строка__число т-адрес" title="частей">${и.частей || '—'}</span><span class="строка__число т-адрес" title="упоминаний в других книгах">${и.отклики || '—'}</span>` : '';
    return `<li class="строка${О.слой2() ? ' строка--второй' : ''}" data-n="${и.номер}">
      <span class="строка__номер">${и.номер}</span>
      <span class="строка__название"><a class="строка__ссылка" href="${href}" aria-describedby="${т ? `${id}-тр` : ''}">${esc(и.название)}</a>${метка}${т ? `<span class="строка__трудное" id="${id}-тр">${esc(т)}</span>` : ''}</span>
      <span class="строка__вид"><span class="вид">${знакВида(и.вид)}${esc(и.вид)}</span><span class="адрес-в-ярусе">${адресТекст(и.адрес, '')}</span>${метка}${т ? `<span class="строка__трудное" aria-hidden="true">${esc(т)}</span>` : ''}</span>
      <span class="строка__адрес">${адресТекст(и.адрес, '')}</span>${доп}
      <button class="строка__подробнее" type="button" aria-expanded="${состояние.открыта === String(и.номер)}" aria-controls="${id}-подр"><span class="видимо-ноутбук">Подробнее</span><span class="видимо-телефон">Ещё</span><span class="скрыто">: ${esc(и.название)}</span>${значок('раскрыть')}</button>
      <div class="строка__раскрытие" id="${id}-подр" ${состояние.открыта === String(и.номер) ? '' : 'hidden'}>${раскрытие(и)}</div>
    </li>`;
  }
  function раскрытие(и) {
    const коротко = и.id === 'e-быт-6-9'
      ? `<p class="подпись-голоса">Коротко, нашими словами</p><p class="т-проза">${Д.ной.о_чём.простой_слой.map((x) => esc(x.текст)).join(' ')} <span class="т-адрес">по стихам ${esc(Д.ной.о_чём.формула.replace('по стихам ', ''))}</span></p>`
      : `<p class="голос-мы">Коротко, нашими словами: этот раздел мы ещё не написали.</p>`;
    const части = и.части.length ? `<dt>Части</dt><dd><ol>${и.части.map((ч, n) => `<li>${n + 1}. ${esc(ч.название)} <span class="т-адрес">${адрес(ч.стихи.replace('–', '-'))}</span></li>`).join('')}</ol></dd>` : '';
    return `${коротко}<dl class="т-интерфейс"><dt>Стихов</dt><dd class="цифры">${и.стихов}</dd>${части}${и.отклики ? `<dt>${О.слой2() ? 'Упоминаний' : 'Вспоминают'}</dt><dd>${О.слой2() ? и.отклики : `ещё ${число(и.отклики, ['место', 'места', 'мест'])} в других книгах`}</dd>` : ''}</dl>`;
  }
  function список() {
    const xs = видимые();
    if (!xs.length) return `<p class="т-проза ч2">По этим фильтрам историй нет. <button class="кн кн--текст" type="button" data-сброс>Сбросить фильтры</button></p>`;
    if (состояние.порядок !== 'библия') return `<p class="т-адрес">Группы скрыты: порядок ${ПОРЯДОК[состояние.порядок]}</p><ul class="список" aria-label="Истории">${xs.map(строка).join('')}</ul>`;
    return кат.повествования.map((п) => {
      const свои = xs.filter((и) => п.истории.includes(и.номер));
      if (!свои.length) return '';
      return `<section class="группа" aria-labelledby="г-${п.id}"><h3 class="группа-заголовок т-повествование" id="г-${п.id}">${esc(п.название)} <span class="группа-число">${число(свои.length, ИСТОРИИ)}</span></h3><ul class="список">${свои.map(строка).join('')}</ul></section>`;
    }).join('');
  }
  function таблица() {
    const xs = видимые();
    const сорт = (ключ, имя) => {
      const тек = (ключ === 'номер' && состояние.порядок === 'библия') || состояние.порядок === ключ;
      return `<th scope="col"${тек ? ` aria-sort="${ключ === 'упоминания' || ключ === 'части' ? 'descending' : 'ascending'}"` : ''}><button type="button" data-сорт="${ключ === 'номер' ? 'библия' : ключ}">${имя}${тек ? значок('сортировка') : ''}</button></th>`;
    };
    const столбцов = О.слой2() ? 7 : 4;
    return `<div class="таблица-обёртка" tabindex="0" role="region" aria-labelledby="табл-подпись"><table class="таблица${столбцов >= 4 ? ' таблица--полосы' : ''}">
      <caption id="табл-подпись">${esc(книга.имя)}: ${число(xs.length, ИСТОРИИ)}, ${ПОРЯДОК[состояние.порядок]}. ${esc(Д.эскиз)}</caption>
      <thead><tr>${сорт('номер', '№')}${сорт('название', 'Название')}<th scope="col">Вид</th><th scope="col">Адрес</th>${О.слой2() ? `${сорт('части', 'Частей')}<th scope="col" class="число">Стихов</th>${сорт('упоминания', 'Упоминаний')}` : ''}</tr></thead>
      <tbody>${xs.map((и) => `<tr><td class="цифры">${и.номер}</td><th scope="row"><a href="история.html${и.id === 'e-быт-6-9' ? '' : `?e=${encodeURIComponent(и.id)}`}">${esc(и.название)}</a></th><td><span class="вид">${знакВида(и.вид)}${esc(и.вид)}</span></td><td>${адресТекст(и.адрес, 'цифры')}</td>${О.слой2() ? `<td class="число">${и.частей || '—'}</td><td class="число">${и.стихов}</td><td class="число">${и.отклики || '—'}</td>` : ''}</tr>`).join('')}</tbody></table></div>`;
  }
  function указатель() {
    const группы = [['ветхий завет', 'ot'], ['новый завет', 'nt']];
    return `<nav class="указатель-книг" aria-label="Книги Библии">${группы.map(([имя, t]) => `<h2 class="т-книга указатель-книг__завет ч-${t === 'ot' ? 'вз' : 'нз'}">${имя}</h2><ul>${Д.книги.filter((b) => b.завет === t).map((b) => {
      const n = Д.каталоги[b.код]?.истории.length ?? 0;
      const тек = b.код === код;
      if (!n) return `<li class="указатель-книг__книга указатель-книг__книга--нет"><span>${esc(b.имя)}</span><span class="цифры">0</span></li>`;
      return `<li class="указатель-книг__книга${тек ? ' указатель-книг__книга--тек' : ''}"><a href="каталог.html?книга=${encodeURIComponent(b.код)}"${тек ? ' aria-current="page"' : ''}>${esc(b.имя)}</a><span class="цифры">${n}</span></li>`;
    }).join('')}</ul>`).join('')}</nav>`;
  }
  function видыСЧислом() {
    const m = new Map(); кат.истории.forEach((и) => m.set(и.вид, (m.get(и.вид) ?? 0) + 1));
    return [...m.entries()].sort((a, b) => b[1] - a[1]);
  }
  function строкаДействий() {
    const n = видимые().length;
    const фильтры = [...состояние.фильтр].map((ф) => `<span class="фильтр-вкл">Вид: ${esc(ф)}. <button class="кн кн--текст" type="button" data-снять="${esc(ф)}">Снять<span class="скрыто"> фильтр: ${esc(ф)}</span></button></span>`).join('');
    return `<div class="строка-действий">
      <p class="строка-действий__число" id="число-историй">${число(n, ИСТОРИИ)}<span class="хвост">, ${ПОРЯДОК[состояние.порядок]}</span></p>
      <div class="меню-обёртка"><button class="кн" type="button" aria-haspopup="menu" aria-expanded="false" data-menu="меню-порядок">${значок('сортировка')}<span>Порядок</span></button>
        <div class="меню" role="menu" id="меню-порядок" hidden aria-label="Порядок">${Object.entries(ПОРЯДОК).filter(([k]) => О.слой2() || k === 'библия' || k === 'название').map(([k, v]) => `<button type="button" role="menuitemradio" aria-checked="${состояние.порядок === k}" data-сорт="${k}">${v[0].toUpperCase() + v.slice(1)}</button>`).join('')}</div></div>
      <div class="меню-обёртка"><button class="кн" type="button" aria-expanded="false" aria-controls="фасеты" data-toggletip>${значок('фильтры')}<span>Фильтры${состояние.фильтр.size ? ` (${состояние.фильтр.size})` : ''}</span></button>
        <div class="меню фасеты" id="фасеты" hidden><fieldset class="радио"><legend>Вид</legend>${видыСЧислом().map(([в, c]) => `<label><input type="checkbox" data-фильтр="${esc(в)}" ${состояние.фильтр.has(в) ? 'checked' : ''}> ${esc(в[0].toUpperCase() + в.slice(1))} — <span class="цифры">${c}</span></label>`).join('')}</fieldset></div></div>
      <span class="ряд-кнопок сегменты" role="group" aria-label="Вид списка"><button class="кн" type="button" data-вид="список" aria-pressed="${состояние.вид === 'список'}">${значок('списком')}<span>Список</span></button><button class="кн" type="button" data-вид="таблица" aria-pressed="${состояние.вид === 'таблица'}">${значок('таблица')}<span>Таблица</span></button></span>
      ${фильтры}${состояние.фильтр.size ? `<button class="кн кн--текст" type="button" data-сброс>Сбросить фильтры</button>` : ''}
    </div>`;
  }
  function отрисовать(фокус) {
    document.getElementById('главное').innerHTML = `<div class="каталог" data-zavet="${завет}">
      ${указатель()}
      <div class="каталог__список">
        <div class="заголовок-книги">
          <h1 class="т-h1" id="h1" tabindex="-1">${esc(книга.имя)}</h1>
          <a class="кн кн--текст другая-книга" href="#указатель-книг-телефон">${значок('списком')}Другая книга</a>
          <p class="т-адрес заголовок-книги__число">${число(кат.истории.length, ИСТОРИИ)}</p>
          <span class="заголовок-книги__слой">${О.переключательСлоя()}</span>
        </div>
        ${строкаДействий()}
        ${кат.охват ? `<p class="голос-мы неполно">${О.слой2() ? esc(`Размечены главы ${кат.охват.главы ?? '1–3'} из ${книга.глав}`) : `Пока здесь истории только из глав 1–3`}</p>` : ''}
        <div id="список">${состояние.вид === 'таблица' ? таблица() : список()}</div>
        <p class="т-адрес эскиз-подпись">${esc(Д.эскиз)}</p>
      </div></div>`;
    if (фокус) document.querySelector(фокус)?.focus();
  }
  function сменить(что, фокус) {
    const u = new URL(location.href);
    состояние.порядок === 'библия' ? u.searchParams.delete('sort') : u.searchParams.set('sort', состояние.порядок);
    состояние.фильтр.size ? u.searchParams.set('f', [...состояние.фильтр].join(',')) : u.searchParams.delete('f');
    history.replaceState(null, '', u); // уровень 3: замена записи (08 § 6.5)
    отрисовать(фокус);
    О.объявить(что);
  }
  document.addEventListener('click', (e) => {
    const t = e.target.closest('[data-сорт],[data-вид],[data-снять],[data-сброс]');
    if (!t) return;
    if (t.dataset.сорт) { состояние.порядок = t.dataset.сорт; сменить(`Порядок: ${ПОРЯДОК[состояние.порядок]}.${состояние.порядок !== 'библия' ? ' Группы по повествованиям скрыты' : ''}`, `[aria-controls="меню-порядок"], [data-menu="меню-порядок"]`); }
    if (t.dataset.вид) { состояние.вид = t.dataset.вид; сменить(`Вид: ${состояние.вид}`, `[data-вид="${состояние.вид}"]`); }
    if (t.dataset.снять) { состояние.фильтр.delete(t.dataset.снять); сменить(`Фильтр снят. ${document.getElementById('число-историй')?.textContent ?? ''}`, '#число-историй'); }
    if (t.dataset.сброс !== undefined) { состояние.фильтр.clear(); сменить('Фильтры сброшены', '#число-историй'); }
  });
  document.addEventListener('change', (e) => {
    const t = e.target.closest('[data-фильтр]');
    if (!t) return;
    t.checked ? состояние.фильтр.add(t.dataset.фильтр) : состояние.фильтр.delete(t.dataset.фильтр);
    сменить(`${число(видимые().length, ИСТОРИИ)}`, `[data-фильтр="${CSS.escape(t.dataset.фильтр)}"]`);
    document.querySelector('[aria-controls="фасеты"]')?.setAttribute('aria-expanded', 'true');
    document.getElementById('фасеты').hidden = false;
  });
  document.addEventListener('слой', () => отрисовать());
  document.addEventListener('DOMContentLoaded', () => {
    О.оболочка({ активный: 'Указатель', панель: q.get('panel') !== '0' });
    document.title = `${книга.имя} — истории — Библия наглядно`;
    отрисовать();
  });
  void NB;
})();
